        for i,(rr,cc) in enumerate(pts):
            val=v if i==0 or i==len(pts)-1 else 5
            if (rr,cc) in owner and owner[(rr,cc)]!=(r,c):
                cross.add((rr,cc))
            owner[(rr,cc)]=(r,c)
